import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_alexnet_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Specialized cooperative tiled Conv2d:
// NCHW float32, Cin=3, K=11x11, stride=4, pad=2, dilation=1.
// Each CTA computes a 16x8 spatial tile for 16 output channels of one batch.
// Each thread reuses one input activation across four output channels.
__device__ __forceinline__ void conv2d_alexnet_accum4(
    const float4 wv, const float xv,
    float& acc0, float& acc1, float& acc2, float& acc3) {
  acc0 += xv * wv.x;
  acc1 += xv * wv.y;
  acc2 += xv * wv.z;
  acc3 += xv * wv.w;
}
template <typename T>
__global__ void conv2d_alexnet_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int OC, int H, int Win,
    int Hout, int Wout)
{
  constexpr int Threads = 256;
  constexpr int TOH = 16;
  constexpr int TOW = 8;
  constexpr int OCC = 16;
  constexpr int CIN = 3;
  constexpr int K = 11;
  constexpr int STRIDE = 4;
  constexpr int PAD = 2;
  constexpr int IHT = (TOH - 1) * STRIDE + K;  // 71
  constexpr int IWT = (TOW - 1) * STRIDE + K;  // 39
  constexpr int IWP = ((IWT + 3) / 4) * 4;     // 40, 16B-aligned rows
  constexpr int SX_SIZE = CIN * IHT * IWP;     // 8520
  constexpr int SW_SIZE = OCC * CIN * K * K;   // 2904
  const int tid = threadIdx.x;
  const int oc_chunks = (OC + OCC - 1) / OCC;
  const int n = blockIdx.z / oc_chunks;
  const int oc_chunk = blockIdx.z - n * oc_chunks;
  const int oc0 = oc_chunk * OCC;
  const int oh0 = blockIdx.y * TOH;
  const int ow0 = blockIdx.x * TOW;
  const int base_ih = oh0 * STRIDE - PAD;
  const int base_iw = ow0 * STRIDE - PAD;
  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(N, Int<CIN>{}, H, Win),
      make_stride((int64_t)CIN * H * Win, (int64_t)H * Win, (int64_t)Win, Int<1>{}));
  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, Int<CIN>{}, Int<K>{}, Int<K>{}),
      make_stride((int64_t)CIN * K * K, (int64_t)K * K, (int64_t)K, Int<1>{}));
  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(N, OC, Hout, Wout),
      make_stride((int64_t)OC * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));
  extern __shared__ __align__(16) T smem_raw[];
  T* sW_raw = smem_raw;
  T* sX_raw = smem_raw + SW_SIZE;
  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CIN>{}, Int<IHT>{}, Int<IWP>{}),
      make_stride(Int<IHT * IWP>{}, Int<IWP>{}, Int<1>{}));
  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CIN>{}, Int<K>{}, Int<K>{}, Int<OCC>{}),
      make_stride(Int<K * K * OCC>{}, Int<K * OCC>{}, Int<OCC>{}, Int<1>{}));
  for (int idx = tid; idx < SW_SIZE; idx += Threads) {
    int c = idx / (K * K * OCC);
    int rem = idx - c * (K * K * OCC);
    int kh = rem / (K * OCC);
    rem -= kh * (K * OCC);
    int kw = rem / OCC;
    int oc_l = rem - kw * OCC;
    int oc_g = oc0 + oc_l;
    T v = T(0);
    if (oc_g < OC) {
      v = mW(oc_g, c, kh, kw);
    }
    sW(c, kh, kw, oc_l) = v;
  }
  for (int idx = tid; idx < SX_SIZE; idx += Threads) {
    int c = idx / (IHT * IWP);
    int rem = idx - c * (IHT * IWP);
    int ih = rem / IWP;
    int iw = rem - ih * IWP;
    T v = T(0);
    if (iw < IWT) {
      int gih = base_ih + ih;
      int giw = base_iw + iw;
      if ((unsigned)gih < (unsigned)H && (unsigned)giw < (unsigned)Win) {
        v = mX(n, c, gih, giw);
      }
    }
    sX(c, ih, iw) = v;
  }
  __syncthreads();
  // 128 threads compute 1024 outputs: each thread handles two adjacent
  // spatial locations (dx, dx+1) for four output channels. Weight values
  // are loaded once per thread and reused for both locations (register
  // blocking over ow), halving shared-memory weight traffic per output.
  const int sp = tid & ((TOH * TOW / 2) - 1);  // 0..63 spatial pairs
  const int oc_quad = tid >> 6;                // 0..1
  const int dy = sp >> 2;                      // / (TOW/2), 0..15
  const int dx = (sp & (TOW / 2 - 1)) * 2;     // 0,2,4,6
  const int oh = oh0 + dy;
  const int ow = ow0 + dx;
  const int ly = dy * STRIDE;
  const int lx = dx * STRIDE;
  const int oc_l0 = oc_quad * 4;               // 0 or 4
  float acc0 = 0.0f;
  float acc1 = 0.0f;
  float acc2 = 0.0f;
  float acc3 = 0.0f;
  float acc4 = 0.0f;
  float acc5 = 0.0f;
  float acc6 = 0.0f;
  float acc7 = 0.0f;
  const int oc_g0 = oc0 + oc_l0;
  const int oc_g1 = oc0 + oc_l0 + 1;
  const int oc_g2 = oc0 + oc_l0 + 2;
  const int oc_g3 = oc0 + oc_l0 + 3;
  if (B != nullptr) {
    if (oc_g0 < OC) { acc0 = (float)B[oc_g0]; acc4 = acc0; }
    if (oc_g1 < OC) { acc1 = (float)B[oc_g1]; acc5 = acc1; }
    if (oc_g2 < OC) { acc2 = (float)B[oc_g2]; acc6 = acc2; }
    if (oc_g3 < OC) { acc3 = (float)B[oc_g3]; acc7 = acc3; }
  }
  #pragma unroll
  for (int c = 0; c < CIN; ++c) {
    #pragma unroll
    for (int kh = 0; kh < K; ++kh) {
      const float4 x0 = *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx));
      const float4 x1 = *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 4));
      const float4 x2 = *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 8));
      const float4 x3 = *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 12));
      float4 wv = *reinterpret_cast<const float4*>(&sW(c, kh, 0, oc_l0));
      conv2d_alexnet_accum4(wv, x0.x, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x1.x, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 1, oc_l0));
      conv2d_alexnet_accum4(wv, x0.y, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x1.y, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 2, oc_l0));
      conv2d_alexnet_accum4(wv, x0.z, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x1.z, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 3, oc_l0));
      conv2d_alexnet_accum4(wv, x0.w, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x1.w, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 4, oc_l0));
      conv2d_alexnet_accum4(wv, x1.x, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x2.x, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 5, oc_l0));
      conv2d_alexnet_accum4(wv, x1.y, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x2.y, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 6, oc_l0));
      conv2d_alexnet_accum4(wv, x1.z, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x2.z, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 7, oc_l0));
      conv2d_alexnet_accum4(wv, x1.w, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x2.w, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 8, oc_l0));
      conv2d_alexnet_accum4(wv, x2.x, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x3.x, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 9, oc_l0));
      conv2d_alexnet_accum4(wv, x2.y, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x3.y, acc4, acc5, acc6, acc7);
      wv = *reinterpret_cast<const float4*>(&sW(c, kh, 10, oc_l0));
      conv2d_alexnet_accum4(wv, x2.z, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x3.z, acc4, acc5, acc6, acc7);
    }
  }
  if (oh < Hout) {
    if (ow < Wout) {
      if (oc_g0 < OC) {
        mY(n, oc_g0, oh, ow) = (T)acc0;
      }
      if (oc_g1 < OC) {
        mY(n, oc_g1, oh, ow) = (T)acc1;
      }
      if (oc_g2 < OC) {
        mY(n, oc_g2, oh, ow) = (T)acc2;
      }
      if (oc_g3 < OC) {
        mY(n, oc_g3, oh, ow) = (T)acc3;
      }
    }
    if (ow + 1 < Wout) {
      if (oc_g0 < OC) {
        mY(n, oc_g0, oh, ow + 1) = (T)acc4;
      }
      if (oc_g1 < OC) {
        mY(n, oc_g1, oh, ow + 1) = (T)acc5;
      }
      if (oc_g2 < OC) {
        mY(n, oc_g2, oh, ow + 1) = (T)acc6;
      }
      if (oc_g3 < OC) {
        mY(n, oc_g3, oh, ow + 1) = (T)acc7;
      }
    }
  }
}
torch::Tensor conv2d_alexnet_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda() && b.is_cuda(), "x, w, b must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  TORCH_CHECK(b.scalar_type() == at::kFloat, "b must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be NCHW");
  TORCH_CHECK(w.dim() == 4, "w must be [OC,3,11,11]");
  TORCH_CHECK(b.dim() == 1, "b must be [OC]");
  const int64_t N = x.size(0);
  const int64_t CIN = x.size(1);
  const int64_t H = x.size(2);
  const int64_t Win = x.size(3);
  const int64_t OC = w.size(0);
  TORCH_CHECK(CIN == 3, "This kernel expects 3 input channels");
  TORCH_CHECK(w.size(1) == 3 && w.size(2) == 11 && w.size(3) == 11,
              "w must be [OC,3,11,11]");
  TORCH_CHECK(b.size(0) == OC, "bias must match out_channels");
  constexpr int64_t STRIDE = 4;
  constexpr int64_t PAD = 2;
  constexpr int64_t K = 11;
  const int64_t Hout = (H + 2 * PAD - K) / STRIDE + 1;
  const int64_t Wout = (Win + 2 * PAD - K) / STRIDE + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output spatial size");
  TORCH_CHECK(N <= INT_MAX && OC <= INT_MAX && H <= INT_MAX && Win <= INT_MAX &&
              Hout <= INT_MAX && Wout <= INT_MAX, "tensor dims too large");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  auto b_c = b.contiguous();
  auto y = torch::empty({N, OC, Hout, Wout}, x_c.options());
  constexpr int Threads = 256;
  constexpr int TOH = 16;
  constexpr int TOW = 8;
  constexpr int OCC = 16;
  constexpr int SM_CIN = 3;
  constexpr int SM_K = 11;
  constexpr int SM_IHT = (TOH - 1) * 4 + SM_K;
  constexpr int SM_IWT = (TOW - 1) * 4 + SM_K;
  constexpr int SM_IWP = ((SM_IWT + 3) / 4) * 4;
  constexpr int SX_SIZE = SM_CIN * SM_IHT * SM_IWP;
  constexpr int SW_SIZE = OCC * SM_CIN * SM_K * SM_K;
  const size_t smem_bytes = (size_t)(SX_SIZE + SW_SIZE) * sizeof(float);
  cudaError_t attr_err = cudaFuncSetAttribute(
      (const void*)conv2d_alexnet_kernel<float>,
      cudaFuncAttributeMaxDynamicSharedMemorySize,
      (int)smem_bytes);
  TORCH_CHECK(attr_err == cudaSuccess, "failed to set max dynamic shared memory: ",
              cudaGetErrorString(attr_err));
  const int64_t oc_chunks = (OC + OCC - 1) / OCC;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)((Wout + TOW - 1) / TOW),
      (unsigned)((Hout + TOH - 1) / TOH),
      (unsigned)(N * oc_chunks));
  TORCH_CHECK(grid.z <= 65535, "grid.z exceeds CUDA limit for this kernel");
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_alexnet_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)N, (int)OC, (int)H, (int)Win,
      (int)Hout, (int)Wout);
  cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_alexnet_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_alexnet_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_alexnet_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        # Parameter container kept for identical initialization/state_dict names;
        # forward() uses only the custom CuTe CUDA kernel below.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        self._ext = conv2d_ext

    def forward(self, x):
        return self._ext.conv2d_alexnet_forward(
            x.contiguous(),
            self.conv1.weight.contiguous(),
            self.conv1.bias.contiguous(),
        )

