import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_alexnet_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Specialized cooperative tiled Conv2d:
// NCHW float32, Cin=3, K=11x11, stride=4, pad=2, dilation=1.
// Each CTA computes a 16x8 spatial tile for 8 output channels of one batch.
// Each thread reuses one input activation across four output channels.
__device__ __forceinline__ void conv2d_alexnet_accum4(
    const float4 wv, const float xv,
    float& acc0, float& acc1, float& acc2, float& acc3) {
  acc0 += xv * wv.x;
  acc1 += xv * wv.y;
  acc2 += xv * wv.z;
  acc3 += xv * wv.w;
}
template <typename T>
__global__ void conv2d_alexnet_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int OC, int H, int Win,
    int Hout, int Wout)
{
