  constexpr int IWT = (TOW - 1) * STRIDE + K;  // 39
  constexpr int IWP = ((IWT + 3) / 4) * 4;     // 40, 16B-aligned rows
  constexpr int SX_SIZE = CIN * IHT * IWP;     // 8520
  constexpr int SW_SIZE = OCC * CIN * K * K;   // 2904
  const int tid = threadIdx.x;
  const int oc_chunks = (OC + OCC - 1) / OCC;
  const int n = blockIdx.z / oc_chunks;
  const int oc_chunk = blockIdx.z - n * oc_chunks;
  const int oc0 = oc_chunk * OCC;
  const int oh0 = blockIdx.y * TOH;
  const int ow0 = blockIdx.x * TOW;
  const int base_ih = oh0 * STRIDE - PAD;
  const int base_iw = ow0 * STRIDE - PAD;
  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(N, Int<CIN>{}, H, Win),
      make_stride((int64_t)CIN * H * Win, (int64_t)H * Win, (int64_t)Win, Int<1>{}));
  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, Int<CIN>{}, Int<K>{}, Int<K>{}),
      make_stride((int64_t)CIN * K * K, (int64_t)K * K, (int64_t)K, Int<1>{}));
  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(N, OC, Hout, Wout),
      make_stride((int64_t)OC * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));
  __shared__ __align__(16) T sW_raw[SW_SIZE];
  __shared__ __align__(16) T sX_raw[SX_SIZE];
  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CIN>{}, Int<IHT>{}, Int<IWP>{}),
      make_stride(Int<IHT * IWP>{}, Int<IWP>{}, Int<1>{}));
  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CIN>{}, Int<K>{}, Int<K>{}, Int<OCC>{}),
      make_stride(Int<K * K * OCC>{}, Int<K * OCC>{}, Int<OCC>{}, Int<1>{}));
  for (int idx = tid; idx < SW_SIZE; idx += Threads) {
    int c = idx / (K * K * OCC);
    int rem = idx - c * (K * K * OCC);
    int kh = rem / (K * OCC);
    rem -= kh * (K * OCC);
    int kw = rem / OCC;
    int oc_l = rem - kw * OCC;
    int oc_g = oc0 + oc_l;
    T v = T(0);
    if (oc_g < OC) {
      v = mW(oc_g, c, kh, kw);
    }
    sW(c, kh, kw, oc_l) = v;
  }
  for (int idx = tid; idx < SX_SIZE; idx += Threads) {
    int c = idx / (IHT * IWP);
    int rem = idx - c * (IHT * IWP);
    int ih = rem / IWP;
    int iw = rem - ih * IWP;
    T v = T(0);
    if (iw < IWT) {
      int gih = base_ih + ih;
      int giw = base_iw + iw;
      if ((unsigned)gih < (unsigned)H && (unsigned)giw < (unsigned)Win) {
        v = mX(n, c, gih, giw);
      }
    }
    sX(c, ih, iw) = v;
  }
  __syncthreads();
  // 128 threads compute 1024 outputs: each thread handles two adjacent
  // spatial locations (dx, dx+1) for four output channels. Weight values
  // are loaded once per thread and reused for both locations (register
  // blocking over ow), halving shared-memory weight traffic per output.
  const int sp = tid & ((TOH * TOW / 2) - 1);  // 0..63 spatial pairs
  const int oc_quad = tid >> 6;                // 0..1
  const int dy = sp >> 2;                      // / (TOW/2), 0..15
  const int dx = (sp & (TOW / 2 - 1)) * 2;     // 0,2,4,6
  const int oh = oh0 + dy;
  const int ow = ow0 + dx;
  const int ly = dy * STRIDE;
  const int lx = dx * STRIDE;
  const int oc_l0 = oc_quad * 4;               // 0 or 4
  float acc0 = 0.0f;
  float acc1 = 0.0f;
  float acc2 = 0.0f;
  float acc3 = 0.0f;
  float acc4 = 0.0f;
  float acc5 = 0.0f;
  float acc6 = 0.0f;
  float acc7 = 0.0f;
  const int oc_g0 = oc0 + oc_l0;
  const int oc_g1 = oc0 + oc_l0 + 1;
  const int oc_g2 = oc0 + oc_l0 + 2;
  const int oc_g3 = oc0 + oc_l0 + 3;
  if (B != nullptr) {
    if (oc_g0 < OC) { acc0 = (float)B[oc_g0]; acc4 = acc0; }
    if (oc_g1 < OC) { acc1 = (float)B[oc_g1]; acc5 = acc1; }
    if (oc_g2 < OC) { acc2 = (float)B[oc_g2]; acc6 = acc2; }
    if (oc_g3 < OC) { acc3 = (float)B[oc_g3]; acc7 = acc3; }
  }
  #pragma unroll
  for (int c = 0; c < CIN; ++c) {
    #pragma unroll
    for (int kh = 0; kh < K; ++kh) {
      const float4 x0 = *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx));
      const float4 x1 = *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 4));
      const float4 x2 = *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 8));
      const float4 x3 = *reinterpret_cast<const float4*>(&sX(c, ly + kh, lx + 12));
      float4 wv = *reinterpret_cast<const float4*>(&sW(c, kh, 0, oc_l0));
      conv2d_alexnet_accum4(wv, x0.x, acc0, acc1, acc2, acc3);
      conv2d_alexnet_accum4(wv, x1.x, acc4, acc5, acc6, acc7);
